function update() {
    // Player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y >= height - PLAYER_SIZE) {
      player.y = height - PLAYER_SIZE;
      player.vy = 0;
      player.onGround = true;
    } else {
      player.onGround = false;
    }

    // Move obstacles
    obstacles.forEach(o => o.x -= SPEED);
    // Remove off‑screen obstacles
    obstacles = obstacles.filter(o => o.x + o.w > 0);

    // Update star field for parallax effect
    stars.forEach(s => {
      s.x -= s.speed;
      if (s.x < 0) s.x = width;
    });

    // Spawn new obstacles
    if (frameCount % Math.floor(OBSTACLE_GAP / SPEED) === 0) spawnObstacle();

    // Collision detection
    for (const o of obstacles) {
      if (o.type === 'spike') {
        const collides =
          player.x < o.x + o.w &&
          player.x + PLAYER_SIZE > o.x &&
          player.y < o.y + o.h &&
          player.y + PLAYER_SIZE > o.y;
        if (collides) running = false;
      } else if (o.type === 'gap') {
        // gap is a hole: if player is over the gap and not jumping enough, lose
        const overGap = player.x + PLAYER_SIZE > o.x && player.x < o.x + o.w;
        if (overGap && player.onGround) { running = false; break; }
      }
    }

    frameCount++;
  }

